using System;
using UnrealBuildTool;
using EpicGames.Core;
using System.IO;

public class CarlaTools :
  ModuleRules
{
  [CommandLine("-verbose")]
  bool Verbose = false;

  [CommandLine("-nv-omniverse")]
  bool EnableNVIDIAOmniverse = false;



  public CarlaTools(ReadOnlyTargetRules Target) :
    base(Target)
  {
    PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
    bEnableExceptions = true;
    bUseRTTI = true;
    
    PublicIncludePaths.Add(ModuleDirectory);

    // The *.def files are generated by CMake (Unreal/CMakeLists.txt) and
    // symlinked into the plugin directory. List each resolved file as an
    // external dependency so UnrealBuildTool rebuilds its cached makefile when
    // a CMake option changes (e.g. ENABLE_ROS2); otherwise an already-built tree
    // silently keeps the old options.
    string ReadDef(string FileName)
    {
      var DefPath = System.IO.Path.Combine(PluginDirectory, FileName);
      var LinkTarget = new FileInfo(DefPath).ResolveLinkTarget(true);
      ExternalDependencies.Add(LinkTarget != null ? LinkTarget.FullName : DefPath);
      return File.ReadAllText(DefPath);
    }

    foreach (var Definition in ReadDef("Definitions.def").Split(';'))
    {
      var Trimmed = Definition.Trim();
      if (Trimmed.Length != 0)
        PrivateDefinitions.Add(Trimmed.Trim());
    }

    foreach (var Path in ReadDef("Includes.def").Split(';'))
    {
      var Trimmed = Path.Trim();
      if (Trimmed.Length != 0)
        PublicIncludePaths.Add(Trimmed.Trim());
    }

    foreach (var Path in ReadDef("Libraries.def").Split(';'))
    {
      var Trimmed = Path.Trim();
      if (Trimmed.Length != 0)
        PublicAdditionalLibraries.Add(Trimmed.Trim());
    }

    foreach (var Option in ReadDef("Options.def").Split(';'))
    {
      string Trimmed = Option.Trim();
      switch (Trimmed)
      {
        case "NV_OMNIVERSE":
          EnableNVIDIAOmniverse = true;
          break;
        default:
          Console.WriteLine($"Unknown option \"{Trimmed}\".");
          break;
      }
    }

    Action<bool, string, string> TestOptionalFeature = (enable, name, definition) =>
    {
      if (enable)
        PrivateDefinitions.Add(definition);
      Console.WriteLine(string.Format("{0} is {1}.", name, enable ? "enabled" : "disabled"));
    };
    

    PublicDependencyModuleNames.AddRange(new string[]
    {
      "Core",
      "LevelEditor",
      "ProceduralMeshComponent",
      "MeshDescription",
      "RawMesh",
      "AssetTools",
    });

    PrivateDependencyModuleNames.AddRange(new string[]
    {
      "CoreUObject",
      "Engine",
      "Slate",
      "SlateCore",
      "UnrealEd",
      "Blutility",
      "UMG",
      "EditorScriptingUtilities",
      "Landscape",
      "Foliage",
      "FoliageEdit",
      "MeshMergeUtilities",
      "Carla",
      "StaticMeshDescription",
      "Json",
      "JsonUtilities",
      "Networking",
      "Sockets",
      "HTTP",
      "RHI",
      "RenderCore",
      "MeshMergeUtilities",
      // "StreetMapImporting",
      // "StreetMapRuntime",
      "Chaos",
      "ChaosVehicles",
      "AssetTools",
      "UnrealEd",
      "EditorStyle",
      "AssetRegistry",
      "MeshDescription",
      "MeshUtilitiesCommon",
      "Projects",
      "PCG",
      // CarlaCrosswalkNavBuilder: package save/delete helpers.
      "SourceControl",
      // carla-digitaltwins port: terrain heightmap sampling, road render
      // export, street-view fetch, TL tool widget, OSM street map access.
      "StreetMapRuntime",
      "StreetMapImporting",
      "ImageWriteQueue",
      "ImageWrapper",
      "ImageCore",
      "EngineSettings",
      "InputCore",
      "AppFramework",
      "DesktopPlatform",
      "LevelEditor",
      // SkyPreviewSubsystem: editor-only sky rig for maps that save none.
      "EditorSubsystem"
    });

    if (EnableNVIDIAOmniverse)
    {
      // @TODO: This should be handled by the (CMake) build system.
      PrivateDefinitions.Add("WITH_OMNIVERSE");

      PrivateDependencyModuleNames.AddRange(new string[]
      {
        "OmniverseUSD",
        "OmniverseRuntime"
      });

      throw new NotImplementedException();
    }

    // OSM2ODR needs no extra library: the converter is compiled into
    // libcarla-server, which this module already links.
  }
}
